  /* arco relaxado / flecha em voo / arco sendo armado */
  arqueira: {
    discRatio: 0.9915,
    angleOffset: 0,
    cycle: [0, 1, 2],
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  /* carregada com virote / corda solta / rearmada vazia */
